import{_ as e,o as n,c as i,a1 as t}from"./chunks/framework.DxqwKiYY.js";const p=JSON.parse('{"title":"Modul 3 - Pengembangan Frontend : Peta Web 3D","description":"","frontmatter":{},"headers":[],"relativePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D.md","filePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D.md"}'),r={name:"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D.md"};function l(s,a,d,o,g,m){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="modul-3-pengembangan-frontend-peta-web-3d" tabindex="-1">Modul 3 - Pengembangan Frontend : Peta Web 3D <a class="header-anchor" href="#modul-3-pengembangan-frontend-peta-web-3d" aria-label="Permalink to &quot;Modul 3 - Pengembangan Frontend : Peta Web 3D&quot;">​</a></h1><h2 id="tujuan-modul" tabindex="-1"><strong>Tujuan Modul</strong> <a class="header-anchor" href="#tujuan-modul" aria-label="Permalink to &quot;**Tujuan Modul**&quot;">​</a></h2><p>Setelah menyelesaikan modul ini, peserta diharapkan mampu untuk memahami dan mengimplementasikan beberapa materi dasar perancangan dan pengembangan WebGIS 3D menggunakan CesiumJS dengan rincian sebagai berikut ini.</p><ol><li>Mengintegrasikan library spasial web CesiumJS ke dalam Framework Next.js.</li><li>Mengkonfigurasi CesiumJS Viewer sebagai dasar untuk membangun tampilan peta WebGIS 3D.</li><li>Menampilkan dan mengelola aset model 3D pada lingkungan WebGIS menggunakan format data 3D yang sesuai.</li><li>Mengintegrasikan dan menampilkan 3D Tiles sebagai salah satu format untuk visualisasi data dan objek 3D.</li><li>Mengintegrasikan data terrain atau elevasi seperti DEM/DTM/DSM ke dalam peta 3D.</li><li>Mengintegrasikan dan menampilkan citra satelit atau peta dasar pada permukaan terrain melalui proses draping.</li><li>Mengatur kamera dan navigasi peta 3D menggunakan fungsi seperti flyTo, setView, serta pengaturan heading, pitch, dan roll.</li><li>Menampilkan dan menggabungkan data spasial 2D dan 3D dalam satu tampilan WebGIS.</li><li>Membuat interaksi pengguna pada peta 3D menggunakan Screen Space Event Handler, seperti interaksi klik dan hover.</li><li>Melakukan 3D Object Picking dan menampilkan informasi semantik objek melalui InfoBox atau tampilan informasi yang dikustomisasi.</li></ol><h2 id="materi" tabindex="-1">Materi <a class="header-anchor" href="#materi" aria-label="Permalink to &quot;Materi&quot;">​</a></h2><p><a href="./Modul 3 - Pengembangan Frontend Peta Web 3D/Konfigurasi Cesium Viewer.html">Konfigurasi Cesium Viewer</a></p><p><a href="./Modul 3 - Pengembangan Frontend Peta Web 3D/Impor dan Pengelolaan Aset 3D dan 3D Tiles.html">Impor dan Pengelolaan Aset 3D dan 3D Tiles</a></p><p><a href="./Modul 3 - Pengembangan Frontend Peta Web 3D/Terrain dan Citra Integrasi Data Elevasi serta Dra.html">Terrain dan Citra: Integrasi Data Elevasi serta Drapping Citra Satelit</a></p><p><a href="./Modul 3 - Pengembangan Frontend Peta Web 3D/Kontrol Kamera dan Navigasi Penggunaaan flyto, set.html">Kontrol Kamera dan Navigasi: <strong>Penggunaaan flyto, setView, heading, pitch dan rol</strong></a></p><p><a href="./Modul 3 - Pengembangan Frontend Peta Web 3D/Visualisasi Data 2D dan 3D.html">Visualisasi Data 2D dan 3D</a></p><p><a href="./Modul 3 - Pengembangan Frontend Peta Web 3D/Interaksi Pengguna.html">Interaksi Pengguna</a></p>',11)])])}const b=e(r,[["render",l]]);export{p as __pageData,b as default};
